import unittest
from candidate import rolling_max

class TestRollingMax(unittest.TestCase):
    def test_normal_sequence(self):
        self.assertEqual(
            rolling_max([1, 2, 3, 2, 3, 4, 2]),
            [1, 2, 3, 3, 3, 4, 4]
        )

    def test_single_element(self):
        self.assertEqual(rolling_max([42]), [42])

    def test_empty_list(self):
        self.assertEqual(rolling_max([]), [])

    def test_monotonic_increasing(self):
        seq = list(range(10))
        expected = [i for i in range(10)]
        self.assertEqual(rolling_max(seq), expected)

    def test_monotonic_decreasing(self):
        seq = list(range(10, 0, -1))
        expected = [10, 10, 10, 10, 10, 10, 10, 10, 10, 10]
        self.assertEqual(rolling_max(seq), expected)

    def test_all_equal_elements(self):
        seq = [7, 7, 7, 7]
        expected = [7, 7, 7, 7]
        self.assertEqual(rolling_max(seq), expected)

    def test_negative_and_positive_numbers(self):
        seq = [-5, -3, -4, 0, 2, -1]
        expected = [-5, -3, -3, 0, 2, 2]
        self.assertEqual(rolling_max(seq), expected)

    def test_float_numbers(self):
        seq = [1.5, 2.3, 1.2, 3.7]
        expected = [1.5, 2.3, 2.3, 3.7]
        self.assertEqual(rolling_max(seq), expected)

    def test_large_integers(self):
        seq = [0, 12345678901234567890, 5]
        expected = [0, 12345678901234567890, 12345678901234567890]
        self.assertEqual(rolling_max(seq), expected)

    def test_original_list_unchanged(self):
        original = [3, 1, 4]
        copy = original[:]
        rolling_max(original)
        self.assertEqual(original, copy)

    def test_generator_input(self):
        gen = (i for i in [1, 3, 2])
        expected = [1, 3, 3]
        self.assertEqual(rolling_max(gen), expected)

    def test_tuple_input(self):
        tup = (4, 2, 5)
        expected = [4, 4, 5]
        self.assertEqual(rolling_max(tup), expected)

    def test_none_as_numbers_argument_raises_type_error(self):
        with self.assertRaises(TypeError):
            rolling_max(None)

    def test_string_in_numbers_raises_type_error(self):
        with self.assertRaises(TypeError):
            rolling_max(["a", "b"])

    def test_list_with_none_element_raises_type_error(self):
        with self.assertRaises(TypeError):
            rolling_max([1, None, 3])

    def test_non_iterable_argument_raises_type_error(self):
        with self.assertRaises(TypeError):
            rolling_max(42)

if __name__ == "__main__":
    unittest.main()
